<?php session_start(); require 'db.php'; require 'commerce.php'; try { commerceRequireAdmin($conn); } catch(Throwable $e) { header('Location: login.php'); exit; } ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý bán khóa học | HànNgữ</title><link rel="stylesheet" href="style.css"><style>.page{max-width:1100px;margin:auto;padding:100px 24px}.grid{display:grid;grid-template-columns:minmax(280px,380px) 1fr;gap:22px}.card{background:#fff;border-radius:16px;padding:22px;box-shadow:0 6px 25px #0f172a12;margin-bottom:20px}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;margin:5px 0 13px;border:1px solid #cbd5e1;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:.9rem}th,td{padding:10px;border-bottom:1px solid #e2e8f0;text-align:left}.paid{color:#047857;font-weight:bold}.pending{color:#b45309;font-weight:bold}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><?php include 'sidebar.php'; ?><main class="page"><h1>Quản lý khóa học & đơn hàng</h1><div class="grid"><section class="card"><h2>Tạo / cập nhật khóa học</h2><form id="courseForm"><input id="id" type="hidden"><label>Tên khóa học</label><input id="title" required><label>Slug không dấu (vd: hsk-1-co-ban)</label><input id="slug" required pattern="[a-z0-9-]+"><label>Mô tả ngắn</label><textarea id="short"></textarea><label>Giá (VND)</label><input id="price" type="number" min="0" required><label>HSK</label><select id="hsk"><option value="">Chuyên đề</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option></select><label><input id="published" type="checkbox" style="width:auto"> Công khai để bán</label><button class="btn btn--primary">Lưu khóa học</button></form><p id="formmsg"></p></section><section><div class="card"><h2>Danh sách khóa học</h2><div id="courses">Đang tải...</div></div><div class="card"><h2>Đơn hàng</h2><p>Chỉ bấm xác nhận khi bạn đã kiểm tra tiền vào tài khoản.</p><div id="orders">Đang tải...</div></div></section></div></main><script>
let token;const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' đ';async function csrf(){if(!token)token=(await fetch('api.php?action=get_csrf_token')).json().then(x=>x.csrf_token);return token}async function load(){let c=await fetch('api.php?action=get_courses').then(x=>x.json());document.getElementById('courses').innerHTML='<table><tr><th>Tên</th><th>Giá</th><th>TT</th></tr>'+c.courses.map(x=>`<tr><td>${x.title}<br><small>${x.slug}</small></td><td>${money(x.price)}</td><td>${x.is_published?'Đang bán':'Nháp'}</td></tr>`).join('')+'</table>';let r=await fetch('api.php?action=admin_list_orders').then(x=>x.json());document.getElementById('orders').innerHTML=r.success?'<table><tr><th>Đơn</th><th>Khách / khóa</th><th>Tiền</th><th>Trạng thái</th><th></th></tr>'+r.orders.map(o=>`<tr><td>${o.order_code}</td><td>${o.username}<br><small>${o.course_title}</small></td><td>${money(o.amount)}</td><td class="${o.status}">${o.status}</td><td>${o.status==='pending'?`<button onclick="confirmPay(${o.id})" class="btn btn--outline">Xác nhận</button>`:o.invoice_number||''}</td></tr>`).join('')+'</table>':'Không tải được đơn hàng.'}async function confirmPay(id){let transaction_id=prompt('Nhập mã giao dịch trên app ngân hàng:');if(!transaction_id)return;let t=await csrf(),r=await fetch('api.php?action=admin_confirm_payment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_id:id,transaction_id,csrf_token:t})}).then(x=>x.json());alert(r.success?'Đã cấp khóa học. '+(r.email_sent?'Email hóa đơn đã gửi.':'SMTP chưa cấu hình nên chưa gửi email.'):r.message);load()}document.getElementById('courseForm').onsubmit=async e=>{e.preventDefault();let t=await csrf(),d={id:+id.value||0,title:title.value,slug:slug.value,short_description:short.value,price:+price.value,hsk_level:hsk.value,is_published:published.checked,csrf_token:t};let r=await fetch('api.php?action=admin_save_course',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(x=>x.json());formmsg.textContent=r.success?'Đã lưu khóa học.':'Lỗi: '+r.message;if(r.success){e.target.reset();load()}};load();
</script></body></html>
